public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int n = first.length();
    if (n == 0) {
        return 0;
    }
    // Helper to reverse a string
    java.util.function.Function<String, String> reverse = s -> new StringBuilder(s).reverse().toString();
    // Search lengths from longest to shortest
    for (int len = n; len >= 1; len--) {
        // Generate all substrings of length len in the first string
        for (int i = 0; i + len <= n; i++) {
            String candidate = first.substring(i, i + len);
            String revCandidate = reverse.apply(candidate);
            boolean valid = true;
            for (String str : strings) {
                if (!(str.contains(candidate) || str.contains(revCandidate))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[grid[i].length];
    }
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // Depth-first search using a stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

