public int minInsertions(String s) {
    int balance = 0;
    int ans = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                ans++;        // need an opening '(' before this ')'
            } else {
                balance--;    // match this ')' with an existing '('
            }
        }
    }
    ans += balance; // add closing ')' for unmatched '('
    return ans;
}

