public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0], maxSoFar = nums[0];
    int minEnding = nums[0], minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    int absMax = Math.max(maxSoFar, -minSoFar);
    return absMax;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[50];
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (fib[size - 1] <= k) {
        fib[size] = fib[size - 1] + fib[size - 2];
        size++;
    }
    int count = 0;
    while (k > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= k) {
                k -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrtN = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k <= 0 || k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

