public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int x : nums) {
        twos |= ones & x;
        ones ^= x;
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    for (int d = 1; d <= 9; d++) {
        Deque<Long> queue = new ArrayDeque<>();
        queue.offer((long) d);
        while (!queue.isEmpty()) {
            long num = queue.poll();
            if (num > high) {
                continue;
            }
            if (num >= low) {
                result.add((int) num);
            }
            long lastDigit = num % 10;
            long next1 = num * 10 + (lastDigit - 1);
            long next2 = num * 10 + (lastDigit + 1);
            if (lastDigit - 1 >= 0 && next1 <= high) {
                queue.offer(next1);
            }
            if (lastDigit + 1 <= 9 && next2 <= high) {
                queue.offer(next2);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long num = n;
    while (factor <= num) {
        long lower = num - (num / factor) * factor;
        long cur = (num / factor) % 10;
        long higher = num / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + (lower + 1);
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

