public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int max = 0;
    int[] vert = new int[n];
    int[] diagPrev = new int[n];
    int[] antiPrev = new int[n];
    for (int i = 0; i < m; i++) {
        int horiz = 0;
        int[] diagCur = new int[n];
        int[] antiCur = new int[n];
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz += 1;
                vert[j] = vert[j] + 1;
                int diag = (i > 0 && j > 0) ? diagPrev[j - 1] + 1 : 1;
                diagCur[j] = diag;
                int anti = (i > 0 && j < n - 1) ? antiPrev[j + 1] + 1 : 1;
                antiCur[j] = anti;
                int curr = Math.max(Math.max(horiz, vert[j]), Math.max(diag, anti));
                if (curr > max) {
                    max = curr;
                }
            } else {
                horiz = 0;
                vert[j] = 0;
                diagCur[j] = 0;
                antiCur[j] = 0;
            }
        }
        diagPrev = diagCur;
        antiPrev = antiCur;
    }
    return max;
}

