public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = 2 * maxVal;
    // Precompute perfect squares up to maxSum
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int x = 0; x * x <= maxSum; x++) {
        isSquare[x * x] = true;
    }
    // Build adjacency matrix
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                adj[i][j] = true;
            }
        }
    }
    int maxMask = 1 << n;
    long[][] dp = new long[maxMask][n];
    // Initialize with single element permutations
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // DP over subsets
    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            // try to append next element
            int remaining = (~mask) & (maxMask - 1);
            for (int next = 0; next < n; next++) {
                if ((remaining & (1 << next)) != 0 && adj[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    long result = 0;
    int fullMask = maxMask - 1;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
