    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int current = (i == n) ? 0 : heights[i];
        while (top != -1 && current < heights[stack[top]]) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    if (n == 0) return new int[0];
    int[] res = new int[m * n];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        if ((s & 1) == 0) { // even diagonal: move up-right
            int r = Math.min(s, m - 1);
            int c = s - r;
            while (r >= 0 && c < n) {
                res[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd diagonal: move down-left
            int c = Math.min(s, n - 1);
            int r = s - c;
            while (c >= 0 && r < m) {
                res[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    int result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'9', '6'}, {'8', '8'} };
    char[] temp = new char[n];
    build(0, n - 1, n, temp, result, pairs);
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute cross product of (p2 - p1) and (p3 - p1)
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) return 0;
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        } else {
            currentLen = 1;
        }
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    while (result.size() < n) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while ((curr % 10 == 9) || (curr + 1 > n)) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        int count = freq.getOrDefault(num, 0);
        freq.put(num, count + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = i; // worst case: all 1^2
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int start = 0;
    int n = s.length();
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) == ' ') {
            // reverse the word before the space
            result.append(new StringBuilder(s, start, i - start).reverse());
            result.append(' ');
            start = i + 1;
        }
    }
    // reverse the last word
    result.append(new StringBuilder(s, start, n - start).reverse());
    return result.toString();
}
